mapper.sql:
select a2.Ad_Id, count(*) as archived from Archive_File af inner join Archive a2 on a2.Ap_Id = af.Ap_Id left join SYS_FileAnnex sfa on sfa.file_id = af.Af_Annex_Id left join ( select dedup_archive.P_Id as project_id, sfa2.File_MD5_Code as file_md5, max(
) as max_key from Archive_File af2 inner join Archive dedup_archive on dedup_archive.Ap_Id = af2.Ap_Id inner join SYS_FileAnnex sfa2 on sfa2.file_id = af2.Af_Annex_Id where sfa2.File_MD5_Code is not null
and dedup_archive.P_Id = #{params.pId}
group by dedup_archive.P_Id, sfa2.File_MD5_Code ) latest_md5 on sfa.File_MD5_Code = latest_md5.file_md5 and (a2.P_Id = latest_md5.project_id or (a2.P_Id is null and latest_md5.project_id is null)) and
= latest_md5.max_key where a2.Ap_State = 1 and af.Af_State = 1
and af.Te_Id = #{params.teId}
and a2.P_Id = #{params.pId}
and ( sfa.File_MD5_Code is null or latest_md5.max_key is not null ) group by a2.Ad_Id

select ranked.Ad_Id, count(*) as archived
from (
select project_files.*,
max(project_files.rank_key) over (
partition by project_files.P_Id, project_files.file_md5
) as max_key
from (
select ar.Ad_Id, ar.P_Id, ar.Ap_State,
af.Af_State, af.Te_Id,
annex.File_MD5_Code as file_md5,

    

as rank_key
from Archive ar
inner join Archive_File af on af.Ap_Id = ar.Ap_Id
left join SYS_FileAnnex annex on annex.file_id = af.Af_Annex_Id

    
        ar.P_Id = #{params.pId}
    

) project_files
) ranked
where ranked.Ap_State = 1
and ranked.Af_State = 1

    and ranked.Te_Id = #{params.teId}

and (ranked.file_md5 is null or ranked.rank_key = ranked.max_key)
group by ranked.Ad_Id

mapper.select:
select c1.C_Name as adRpBuildName, c2.C_Name as adRpConstructionName, c3.C_Name as adRpDesignName, c4.C_Name as adRpSupervisorName, c1.C_Abbreviation as adRpBuildAbbName, c2.C_Abbreviation as adRpConstructionAbbName, c3.C_Abbreviation as adRpDesignAbbName, c4.C_Abbreviation as adRpSupervisorAbbName, ifnull(af_stat.archived, 0) as archived, ifnull(child_stat.childCount, 0) as childCount, mn.* from Archive_Directory mn left join SYS_Company c1 on mn.Ad_Rp_Build=c1.C_Id left join SYS_Company c2 on mn.Ad_Rp_Construction=c2.C_Id left join SYS_Company c3 on mn.Ad_Rp_Design=c3.C_Id left join SYS_Company c4 on mn.Ad_Rp_Supervisor=c4.C_Id left join ( select ad.Ad_Parent_Id, count(*) as childCount from Archive_Directory ad group by ad.Ad_Parent_Id ) child_stat on child_stat.Ad_Parent_Id = mn.Ad_Id left join (
) af_stat on af_stat.Ad_Id = mn.Ad_Id
and mn.Te_Id = #{params.teId}
and mn.Ad_Type='01'
and mn.Ad_Type=#{params.adType}
order by Ad_Order asc

select c1.C_Name as adRpBuildName, c2.C_Name as adRpConstructionName, c3.C_Name as adRpDesignName, c4.C_Name as adRpSupervisorName, c1.C_Abbreviation as adRpBuildAbbName, c2.C_Abbreviation as adRpConstructionAbbName, c3.C_Abbreviation as adRpDesignAbbName, c4.C_Abbreviation as adRpSupervisorAbbName,
coalesce(file_stat.notArchived, 0) as notArchived, coalesce(file_stat.archived, 0) as archived,
coalesce(child_stat.childCount, 0) as childCount, mn.* from Archive_Directory mn left join SYS_Company c1 on mn.Ad_Rp_Build=c1.C_Id left join SYS_Company c2 on mn.Ad_Rp_Construction=c2.C_Id left join SYS_Company c3 on mn.Ad_Rp_Design=c3.C_Id left join SYS_Company c4 on mn.Ad_Rp_Supervisor=c4.C_Id left join ( select Ad_Parent_Id, count(*) as childCount from Archive_Directory group by Ad_Parent_Id ) child_stat on child_stat.Ad_Parent_Id = mn.Ad_Id
left join (
) file_stat on file_stat.Ad_Id = mn.Ad_Id
and mn.Ad_Parent_Id=#{adId}
and mn.Ad_Type=#{adType}
and mn.Ad_State=#{adState}
and mn.Ad_Type='01'
order by Ad_Order asc

select c1.C_Name as adRpBuildName, c2.C_Name as adRpConstructionName, c3.C_Name as adRpDesignName, c4.C_Name as adRpSupervisorName, c1.C_Abbreviation as adRpBuildAbbName, c2.C_Abbreviation as adRpConstructionAbbName, c3.C_Abbreviation as adRpDesignAbbName, c4.C_Abbreviation as adRpSupervisorAbbName, mn.* from Archive_Directory mn left join SYS_Company c1 on mn.Ad_Rp_Build=c1.C_Id left join SYS_Company c2 on mn.Ad_Rp_Construction=c2.C_Id left join SYS_Company c3 on mn.Ad_Rp_Design=c3.C_Id left join SYS_Company c4 on mn.Ad_Rp_Supervisor=c4.C_Id
and mn.Te_Id = #{params.teId}
and mn.AD_Type=#{params.adType}
order by mn.Ad_Order asc
